hone":"+7 495 104-35-70","email":"b2b@pestcontrol-center.ru"},"areaServed":[{"@type":"City","name":"Москва"},{"@type":"AdministrativeArea","name":"Московская область"}],"audience":{"@type":"BusinessAudience","audienceType":"Магазины, супермаркеты, дарксторы и торговые сети"},"offers":{"@type":"AggregateOffer","priceCurrency":"RUB","lowPrice":3500,"offerCount":3},"hasOfferCatalog":{"@type":"OfferCatalog","name":"Пест-контроль для магазинов и торговых сетей","itemListElement":[{"@type":"Offer","name":"Пест-контроль магазина по договору (1–2 визита в месяц)","priceCurrency":"RUB","price":3900,"priceSpecification":{"@type":"UnitPriceSpecification","minPrice":3900,"priceCurrency":"RUB","unitText":"в месяц","unitCode":"MON"}},{"@type":"Offer","name":"Пест-контроль склада или распределительного центра до 1 000 м²","priceCurrency":"RUB","price":4500,"priceSpecification":{"@type":"UnitPriceSpecification","minPrice":4500,"priceCurrency":"RUB","unitText":"в месяц","unitCode":"MON"}},{"@type":"Offer","name":"Разовая обработка магазина от грызунов или насекомых","priceCurrency":"RUB","price":3500,"priceSpecification":{"@type":"UnitPriceSpecification","minPrice":3500,"priceCurrency":"RUB","unitText":"за выезд"}}]}},{"@type":"FAQPage","@id":"https://xn----itbbsflddbfpfdodg9d0f.xn--p1ai/magaziny-i-torgovye-seti/#faq","mainEntity":[{"@type":"Question","name":"Какие санитарные правила для магазинов действуют с 1 сентября 2026 года?","acceptedAnswer":{"@type":"Answer","text":"Для магазинов, которые продают пищевую продукцию, — СП 2.3.6.4281-26: они заменили СП 2.3.6.3668-20. По п. 78 в помещениях не должно быть насекомых и грызунов, а дезинсекцию и дератизацию, включая защиту здания от проникновения, проводят в порядке и с периодичностью, которые определяет сам магазин с учётом СанПиН 3.3686-21. Для непродовольственных магазинов действует СП 2.1.4284-26 (п. 14). Оба документа действуют с 01.09.2026 по 01.09.2032."}},{"@type":"Question","name":"Как часто нужно проводить дератизацию и дезинсекцию в продуктовом магазине?","acceptedAnswer":{"@type":"Answer","text":"Организации, которые хранят и продают пищевую продукцию, относятся к объектам особого эпидемиологического значения (п. 98 СанПиН 3.3686-21). Обследования на насекомых — не реже 2 раз в месяц (п. 101), по грызунам — ежемесячная оценка, и по её результатам проводится дератизация (п. 110). Истребительные обработки делаем по показаниям мониторинга, а не по календарю."}},{"@type":"Question","name":"Можно ли проводить обработку, не закрывая магазин?","acceptedAnswer":{"@type":"Answer","text":"Да, большую часть работ. Осмотр точек, замена вкладышей и приманок, гели в щелях проводим в рабочее время — магазин и сеть продолжают торговать. Закрыть магазин нужно только для дезинфекции орошением (влажной обработки), если она требуется: её проводим в отсутствие покупателей и персонала (п. 14 СП 2.1.4284-26) — ночью, до открытия или в санитарный день. Ночные и выходные окна — без наценки."}},{"@type":"Question","name":"Как проходит уничтожение тараканов в магазине и нужно ли выносить товар?","acceptedAnswer":{"@type":"Answer","text":"Сначала ищем очаги по клеевым мониторам: пекарня, кулинария, моторные отсеки витрин, помещения персонала. Затем гель точечно наносится в щели и закрытые зоны — товар остаётся на полках, а контрольный осмотр через 10–14 дней показывает результат. Если нужна обработка распылением, продукцию заранее убирают или укрывают — список подготовки директор магазина получает до визита."}},{"@type":"Question","name":"Как устроена работа с сетью магазинов?","acceptedAnswer":{"@type":"Answer","text":"Один договор: магазины перечислены в приложении, график визитов общий, цена — по каждому адресу. В каждом магазине — своя схема точек, журнал и папка документов. Раз в месяц сеть получает сводный отчёт по всем магазинам: визиты, находки, превышения и рекомендации."}},{"@type":"Question","name":"Какие документы должны быть в магазине на случай проверки?","acceptedAnswer":{"@type":"Answer","text":"Договор с исполнителем, копия его лицензии, программа пест-контроля, схема точек контроля, журнал учёта с записями визитов, акты выполненных работ, СГР и инструкции на применяемые средства. Образцы программы и журнала есть в разделе «Материалы»."}},{"@type":"Question","name":"Кто отвечает за пест-контроль магазина в торговом центре?","acceptedAnswer":{"@type":"Answer","text":"За своё помещение отвечает тот, кто в нём торгует: требования п. 78 СП 2.3.6.4281-26 и п. 14 СП 2.1.4284-26 адресованы хозяйствующему субъекту. Общие зоны ТЦ обычно обслуживает подрядчик управляющей компании; как распределены зоны, указано в договоре аренды. Мы стыкуем свои схемы и графики с подрядчиком ТЦ."}},{"@type":"Question","name":"Что грозит магазину, если на проверке найдут грызунов или насекомых?","acceptedAnswer":{"@type":"Answer","text":"Предписание и административная ответственность. Например, за нарушение санитарных требований к эксплуатации общественных помещений юрлицу грозит штраф от 10 до 20 тыс. ₽ или приостановление деятельности на срок до 90 суток (ст. 6.4 КоАП РФ). Для магазина приостановление обходится дороже любого абонемента."}},{"@type":"Question","name":"Как быстро вы приезжаете, если в магазине увидели мышь?","acceptedAnswer":{"@type":"Answer","text":"По договору внеплановый выезд — в течение 3 часов, срочные выезды работают 24/7. Специалист ищет путь проникновения, ставит дополнительные точки, делает запись в журнале и даёт директору список того, что закрыть или отремонтировать."}},{"@type":"Question","name":"Есть ли у вас лицензия и работаете ли вы с НДС?","acceptedAnswer":{"@type":"Answer","text":"Да. С 01.03.2025 дезинфекция, дезинсекция и дератизация требуют лицензии; работы выполняются по лицензии ООО «Центр дезинфекционных услуг» № Л064-00111-77/01942445. Работаем с НДС и без НДС, договор и акты подписываем по ЭДО или на бумаге."}}]}]}</script>
